const ROLES = [
  { key: "P", label: "Portieri", need: 3, color: "#f59e0b" },
  { key: "D", label: "Difensori", need: 8, color: "#10b981" },
  { key: "C", label: "Centrocampisti", need: 8, color: "#3b82f6" },
  { key: "A", label: "Attaccanti", need: 6, color: "#ef4444" },
];
const TOTAL_BUDGET = 500;
const SQUAD_SIZE = 25;
const ROLE_MAP = Object.fromEntries(ROLES.map((r) => [r.key, r]));

// quota tipica di budget per reparto (deve sommare ~1): P poco, A tanto
const ROLE_BUDGET_SHARE = { P: 0.08, D: 0.14, C: 0.28, A: 0.5 };

let idc = 0;
const INIT_PLAYERS = LISTINO.map((p) => ({
  id: `L${idc++}`,
  name: p.n,
  team: p.s,
  role: p.r,
  q: p.q,
  owner: null, // null = disponibile, altrimenti index squadra 0..7
  paid: 0,
  target: false,
}));

// Dati di analisi statici (non salvati in localStorage): statistiche 25/26,
// previsione post-mercato 26/27 e consiglio Goal.com. Indicizzati per id "L{n}".
const ANALISI = {};
LISTINO.forEach((p, i) => {
  ANALISI["L" + i] = {
    score: p.score, scoreHist: p.score_hist, fm: p.fm, gf: p.gf, ass: p.ass,
    pv25: p.pv25, pv26: p.pv26, fm26: p.fm26, aff: p.aff, trend: p.trend,
    prev: p.prev, verd: p.verd, prezzo: p.prezzo, fvm: p.fvm,
    goal: p.goal, goalnote: p.goalnote, fascia: p.fascia, rm: p.rm,
  };
});
const getAnalisi = (id) => ANALISI[id] || {};

const TEAM_NAMES = ["Angelo", "Loriano", "Linneo", "Jason", "Bryan", "Serra", "Sastre", "Alessio"];
const INIT_TEAMS = TEAM_NAMES.map((name, i) => ({ id: i, name }));

// --- Gestione accessi ---
// team  = una delle 8 squadre: vede Asta e Lega
// admin = gestore lega: vede Asta e Lega + poteri (Excel), NIENTE Analisi
// dev   = sviluppatore (password): vede TUTTO, Analisi compresa, + poteri
const DEV_PASSWORD = "ZoeBella";
const canSeeAnalysis = (user) => !!user && user.kind === "dev";
const canManage = (user) => !!user && (user.kind === "dev" || user.kind === "admin");

const USER_KEY = "astaFantaUser_v2";

function loadUser() {
  try {
    const raw = localStorage.getItem(USER_KEY);
    if (!raw) return null;
    const u = JSON.parse(raw);
    if (!u || !u.kind) return null;
    return u;
  } catch (e) { return null; }
}

function ResponsiveStyles() {
  useEffect(() => {
    // viewport per tablet/mobile
    let vp = document.querySelector('meta[name="viewport"]');
    if (!vp) {
      vp = document.createElement("meta");
      vp.name = "viewport";
      document.head.appendChild(vp);
    }
    vp.setAttribute("content", "width=device-width, initial-scale=1, viewport-fit=cover");

    // CSS globale con media query (gli stili inline non le supportano)
    const css = `
      * { box-sizing: border-box; }
      html, body { margin: 0; -webkit-text-size-adjust: 100%; }
      .af-scroll { -webkit-overflow-scrolling: touch; }
      /* la tabella Analisi scorre in orizzontale su schermi stretti */
      /* griglia squadre Lega: 2 colonne di default, 1 sotto i 720px */
      @media (max-width: 720px) {
        .af-league-grid { grid-template-columns: 1fr !important; }
        .af-market-grid { grid-template-columns: repeat(2, 1fr) !important; }
        .af-live-layout { grid-template-columns: 1fr !important; }
        .af-live-actions { position: static !important; }
        .af-header-actions { flex-wrap: wrap; justify-content: flex-end; }
      }
      /* su schermi molto piccoli i bottoni prezzo restano leggibili */
      @media (max-width: 420px) {
        .af-price-btns button { min-width: 40px; }
      }
      /* target touch: bottoni un filo più comodi da toccare su tablet/telefono */
      @media (pointer: coarse) {
        button { touch-action: manipulation; }
      }
      /* i menu a tendina non si rimpiccioliscono troppo */
      select, input { font-size: 16px; } /* evita lo zoom automatico iOS sui campi */
    `;
    let tag = document.getElementById("af-responsive-styles");
    if (!tag) {
      tag = document.createElement("style");
      tag.id = "af-responsive-styles";
      document.head.appendChild(tag);
    }
    tag.textContent = css;
  }, []);
  return null;
}

export default function App() {
  const [players, setPlayers] = useState(INIT_PLAYERS);
  const [teams, setTeams] = useState(INIT_TEAMS);
  const [currentUser, setCurrentUser] = useState(() => (typeof window !== "undefined" ? loadUser() : null)); // {kind, teamId?}
  const [view, setView] = useState("auction"); // "analysis" | "auction" | "league"
  const [syncState, setSyncState] = useState("connecting"); // connecting | online | offline

  const applyingRemote = useRef(false); // evita di riscrivere ciò che arriva dal cloud
  const loaded = useRef(false);         // primo caricamento avvenuto
  const saveTimer = useRef(null);       // debounce dei salvataggi

  // salva l'utente loggato (solo locale: il ruolo è personale del dispositivo)
  useEffect(() => {
    try {
      if (!currentUser) localStorage.removeItem(USER_KEY);
      else localStorage.setItem(USER_KEY, JSON.stringify(currentUser));
    } catch (e) {}
  }, [currentUser]);

  // ---- Caricamento iniziale + sottoscrizione realtime ----
  useEffect(() => {
    if (!supabase) { setSyncState("offline"); loaded.current = true; return; }
    let channel;
    let cancelled = false;

    const applyRow = (row) => {
      if (!row) return;
      applyingRemote.current = true;
      if (Array.isArray(row.players)) setPlayers(row.players);
      if (Array.isArray(row.teams)) setTeams(row.teams);
      // sblocco al ciclo successivo, così l'effetto di save non riparte
      setTimeout(() => { applyingRemote.current = false; }, 0);
    };

    (async () => {
      try {
        const { data, error } = await supabase.from("asta_stato").select("*").eq("id", STATE_ROW_ID).single();
        if (cancelled) return;
        if (!error && data) {
          // se il cloud è vuoto (prima volta in assoluto), lo inizializzo col listone
          const emptyCloud = !Array.isArray(data.players) || data.players.length === 0;
          if (emptyCloud) {
            await supabase.from("asta_stato").update({ players: INIT_PLAYERS, teams: INIT_TEAMS }).eq("id", STATE_ROW_ID);
            applyRow({ players: INIT_PLAYERS, teams: INIT_TEAMS });
          } else {
            applyRow(data);
          }
          setSyncState("online");
        } else {
          setSyncState("offline");
        }
      } catch (e) {
        setSyncState("offline");
      }
      loaded.current = true;
    })();

    // realtime: quando la riga cambia (da chiunque), aggiorno lo schermo
    channel = supabase
      .channel("asta_stato_ch")
      .on("postgres_changes", { event: "*", schema: "public", table: "asta_stato", filter: `id=eq.${STATE_ROW_ID}` },
        (payload) => { if (payload.new) applyRow(payload.new); })
      .subscribe((status) => {
        if (status === "SUBSCRIBED") setSyncState("online");
      });

    return () => { cancelled = true; if (channel) supabase.removeChannel(channel); };
  }, []);

  // ---- Salvataggio su cloud ad ogni modifica (debounce) ----
  useEffect(() => {
    if (!loaded.current) return;        // non salvare durante il primo caricamento
    if (applyingRemote.current) return; // non risalvare ciò che è appena arrivato dal cloud
    if (!supabase) return;
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      try {
        await supabase.from("asta_stato").update({ players, teams, updated_at: new Date().toISOString() }).eq("id", STATE_ROW_ID);
      } catch (e) { /* offline momentaneo */ }
    }, 400);
    return () => { if (saveTimer.current) clearTimeout(saveTimer.current); };
  }, [players, teams]);

  const login = (user) => {
    setCurrentUser(user);
    setView(canSeeAnalysis(user) ? "analysis" : "auction");
  };
  const logout = () => { setCurrentUser(null); setView("auction"); };

  const stats = useMemo(() => {
    return teams.map((t) => {
      const roster = players.filter((p) => p.owner === t.id);
      const spent = roster.reduce((s, p) => s + (p.paid || 0), 0);
      const counts = {};
      ROLES.forEach((r) => (counts[r.key] = roster.filter((p) => p.role === r.key).length));
      const remaining = TOTAL_BUDGET - spent;
      const slotsLeft = SQUAD_SIZE - roster.length;
      const maxBid = Math.max(0, remaining - Math.max(0, slotsLeft - 1));
      return { ...t, roster, spent, remaining, counts, slotsLeft, maxBid };
    });
  }, [players, teams]);

  const assign = (playerId, owner, paid) =>
    setPlayers((ps) => ps.map((p) => (p.id === playerId ? { ...p, owner, paid: paid ?? p.paid } : p)));
  const release = (playerId) =>
    setPlayers((ps) => ps.map((p) => (p.id === playerId ? { ...p, owner: null, paid: 0 } : p)));
  const toggleTarget = (id) =>
    setPlayers((ps) => ps.map((p) => (p.id === id ? { ...p, target: !p.target } : p)));
  const renameTeam = (id, name) =>
    setTeams((ts) => ts.map((t) => (t.id === id ? { ...t, name } : t)));
  const resetAll = () => {
    if (confirm("Azzerare tutti gli acquisti di tutte le squadre?"))
      setPlayers((ps) => ps.map((p) => ({ ...p, owner: null, paid: 0 })));
  };
  const exportExcel = () => {
    const wb = XLSX.utils.book_new();
    const ROLE_ORDER = { P: 0, D: 1, C: 2, A: 3 };

    // --- Foglio riepilogo ---
    const summary = [["Squadra", "Giocatori", "Spesi", "Crediti rimasti", "P", "D", "C", "A"]];
    stats.forEach((t) => {
      summary.push([
        t.name, t.roster.length, t.spent, t.remaining,
        t.counts.P, t.counts.D, t.counts.C, t.counts.A,
      ]);
    });
    const wsSum = XLSX.utils.aoa_to_sheet(summary);
    wsSum["!cols"] = [{ wch: 16 }, { wch: 10 }, { wch: 8 }, { wch: 15 }, { wch: 4 }, { wch: 4 }, { wch: 4 }, { wch: 4 }];
    XLSX.utils.book_append_sheet(wb, wsSum, "Riepilogo");

    // --- Un foglio per squadra ---
    stats.forEach((t) => {
      const rows = [["Ruolo", "Giocatore", "Squadra", "Prezzo pagato"]];
      const roster = [...t.roster].sort(
        (a, b) => (ROLE_ORDER[a.role] - ROLE_ORDER[b.role]) || (b.paid - a.paid)
      );
      roster.forEach((p) => rows.push([p.role, p.name, p.team, p.paid]));
      rows.push([]);
      rows.push(["", "", "TOTALE SPESO", t.spent]);
      rows.push(["", "", "CREDITI RIMASTI", t.remaining]);
      rows.push(["", "", "SLOT RIEMPITI", `${t.roster.length}/${SQUAD_SIZE}`]);
      const ws = XLSX.utils.aoa_to_sheet(rows);
      ws["!cols"] = [{ wch: 6 }, { wch: 22 }, { wch: 14 }, { wch: 14 }];
      // nome foglio max 31 char, no caratteri vietati
      const safe = t.name.replace(/[\\/?*\[\]:]/g, "").slice(0, 28) || `Sq${t.id + 1}`;
      XLSX.utils.book_append_sheet(wb, ws, safe);
    });

    const date = new Date().toISOString().slice(0, 10);
    XLSX.writeFile(wb, `asta-fanta_${date}.xlsx`);
  };

  // ---- schermata di login ----
  if (!currentUser) {
    return <LoginScreen onLogin={login} />;
  }

  const isDev = canSeeAnalysis(currentUser);
  const canMng = canManage(currentUser);
  // nome mostrato in alto
  const userLabel = currentUser.kind === "dev" ? "Developer" : currentUser.kind === "admin" ? "Admin lega" : INIT_TEAMS[currentUser.teamId].name;
  // se non autorizzato ma per qualche motivo è sulla vista analisi, riporta all'asta
  const safeView = view === "analysis" && !isDev ? "auction" : view;

  return (
    <div style={{ maxWidth: safeView === "analysis" || safeView === "league" || safeView === "auction" ? 1100 : 760, width: "100%", margin: "0 auto", padding: "16px clamp(10px, 3vw, 16px)", fontFamily: "system-ui, sans-serif", color: "#1e293b" }}>
      <ResponsiveStyles />
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4, gap: 8, flexWrap: "wrap" }}>
        <h1 style={{ fontSize: 22, fontWeight: 800, margin: 0 }}>⚽ Asta Fanta</h1>
        <div className="af-header-actions" style={{ display: "flex", gap: 6, alignItems: "center" }}>
          <span title={syncState === "online" ? "Sincronizzato in tempo reale" : syncState === "connecting" ? "Connessione..." : "Offline: modifiche non condivise"}
            style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 700, color: syncState === "online" ? "#16a34a" : syncState === "connecting" ? "#d97706" : "#dc2626" }}>
            <span style={{ width: 8, height: 8, borderRadius: 999, background: syncState === "online" ? "#16a34a" : syncState === "connecting" ? "#d97706" : "#dc2626", display: "inline-block" }} />
            {syncState === "online" ? "live" : syncState === "connecting" ? "..." : "offline"}
          </span>
          <span style={{ fontSize: 13, color: "#64748b", marginRight: 2 }}>{userLabel}</span>
          {canMng && <button onClick={exportExcel} style={btnGhost}><Download size={14} /> Excel</button>}
          <button onClick={logout} style={btnGhost} title="Cambia utente"><X size={14} /> Esci</button>
        </div>
      </div>

      {/* Tabs */}
      <div style={{ display: "flex", gap: 6, marginBottom: 16, background: "#f1f5f9", padding: 4, borderRadius: 12 }}>
        {isDev && <button onClick={() => setView("analysis")} style={safeView === "analysis" ? tabOn : tabOff}><BarChart3 size={15} /> Analisi</button>}
        <button onClick={() => setView("auction")} style={safeView === "auction" ? tabOn : tabOff}><Gavel size={15} /> Asta</button>
        <button onClick={() => setView("league")} style={safeView === "league" ? tabOn : tabOff}><Users size={15} /> Lega</button>
      </div>

      {safeView === "analysis" && isDev && (
        <AnalysisView players={players} teams={teams} stats={stats} assign={assign} toggleTarget={toggleTarget} />
      )}
      {safeView === "auction" && (
        <LiveView players={players} teams={teams} assign={assign} />
      )}
      {safeView === "league" && (
        <LeagueView stats={stats} players={players} release={release} renameTeam={renameTeam} />
      )}
    </div>
  );
}

